 p=argparse.ArgumentParser();p.add_argument('--mode',choices=['free','contrib-llvm'],required=True);p.add_argument('--phase',choices=['gu','down'],required=True);p.add_argument('--rows',type=int,choices=[1,8,16,128,129,256,384,512],required=True);p.add_argument('--serial',type=int,required=True);p.add_argument('--debug',action='store_true');a=p.parse_args();assert 1<=a.serial<=3
 with (B/'owned-v0141-measurement.lock').open('a') as lock:
