   cell=dict(v.split('=',1) for v in found[0].split()[1:]);assert cell['status']=='PASS' and cell['scope']=='synthetic_profiling_queue' and cell['phase']==a.phase and int(cell['max_rows'])==a.rows
   assert cell['operands']==cell['bounds']=='device_usm' and cell['backend'] in ['XMX','joint_matrix','DP4a'] and int(cell['groups'])==16
   t0=int(cell['start_ns']);t1=int(cell['end_ns']);assert t0>0 and t1>t0 and t1-t0==int(cell['event_ns'])
   assert 0<int(cell['gpu_requested_bytes'])<=192<<20 and 0<int(cell['host_capacity_bytes'])<=192<<20
   for name in ['host_submit_us','host_completion_us','h2d_host_us','d2h_host_us','wholecell_host_us','bounds_validation_host_us']:assert math.isfinite(float(cell[name])) and float(cell[name])>0
   r['cell']=cell
   files={}
   for capture in r['live_mapping_captures']:
